#include <bits/stdc++.h>
using namespace std;

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353LL;

        long long add(long long a, long long b) {
            a %= MOD; b %= MOD;
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        long long subtract(long long a, long long b) {
            a %= MOD; b %= MOD;
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        long long mult(long long a, long long b) {
            a %= MOD; b %= MOD;
            return (a * b) % MOD;
        }

        long long pow(long long base, long long exp) {
            long long result = 1;
            base %= MOD;
            while (exp > 0) {
                if (exp & 1) result = (result * base) % MOD;
                base = (base * base) % MOD;
                exp >>= 1;
            }
            return result;
        }

        long long inv(long long a) {
            // Fermat's little theorem, since MOD is prime
            return pow(a, MOD - 2);
        }

        long long smallInv(long long a) {
            return inv(a);
        }

        long long ncr(long long n, long long r) {
            if (r > n || r < 0) return 0;
            long long numerator = 1;
            long long denominator = 1;
            for (long long i = 1; i <= r; i++) {
                numerator = mult(numerator, n - i + 1);
                denominator = mult(denominator, i);
            }
            return mult(numerator, inv(denominator));
        }
    };
};

struct HZSShufflesCards {
    NumberTheory::Mod998 mod;

    void solve() {
        ios::sync_with_stdio(false);
        cin.tie(nullptr);
        int n, m;
        cin >> n >> m;

        // precompute inverse of (n + m)
